<td><a class="session-location" href="/chat/index.php?chat=<?=rawurlencode($r['chat'])?>"><?php if($r['location_thumbnail']): ?><img src="<?=$h($r['location_thumbnail'])?>" alt="" width="52" height="39" loading="lazy"><?php else: ?><span class="session-location-fallback" data-icon="map" aria-hidden="true"></span><?php endif; ?><span><?=$h($r['location_label'])?></span></a></td>
<td><time datetime="<?=date('c',(int)$r['datain'])?>"><?=FormatTimestamp((int)$r['datain'])?></time></td><td><?php if($r['dataout']): ?><time datetime="<?=date('c',(int)$r['dataout'])?>"><?=FormatTimestamp((int)$r['dataout'])?></time><?php else: ?>—<?php endif; ?></td>
<td><div class="session-actions"><a href="?azione=pareri&amp;id=<?=(int)$r['id']?>" class="action-btn" data-icon="messages" title="Pareri" aria-label="Pareri"></a><a href="/statistiche/ricompense.php?sessione=<?=(int)$r['id']?>" class="action-btn" data-icon="coins" title="Ricompense" aria-label="Ricompense"></a>
<?php if($isSessionAdmin&&!((int)$r['run'])): ?><form method="post" action="/sessione/viewlog.php" data-session-delete="<?=$h($r['nome'])?>"><input type="hidden" name="azione" value="cancella"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><input type="hidden" name="_csrf" value="<?=$h(alphano_csrf_token())?>"><button type="submit" class="action-btn" data-icon="x" title="Cancella sessione" aria-label="Cancella sessione"></button></form><?php endif; ?></div></td></tr>
